<script setup>
import {useAccess} from '../composables/access.js';
const {can}=useAccess();
import {onMounted,reactive,ref} from 'vue';
import {useContext} from '../composables/context.js';
import {api} from '../services/accounting.js';
import {downloadFile} from '../services/documentation.js';
import {verifactuError,fiscalStatus} from '../services/verifactu.js';
const {company}=useContext(),state=ref(null),records=ref([]),busy=ref(false),error=ref(''),notice=ref('');
const fields=['producer_name','producer_nif','software_name','software_id','version','installation_id'],form=reactive({enabled:false,environment:'test',producer_source:'company',producer_name:'',producer_nif:'',software_name:'Contabilidad',software_id:'CT',version:'0.1.0',installation_id:''});
async function load(){const [settings,rows]=await Promise.all([api('/verifactu'),api('/verifactu/records')]);state.value=settings;records.value=rows;for(const key of ['enabled','environment','producer_source',...fields])form[key]=settings.settings[key];}
function producerChanged(){if(form.producer_source==='company'&&!state.value.counts.total){form.producer_name=state.value.company.name;form.producer_nif=String(state.value.company.tax_id||'').replace(/\s/g,'').toUpperCase();}}
async function save(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{state.value=await api('/verifactu/settings',{method:'PUT',body:{enabled:form.enabled,environment:'test',producer_source:form.producer_source,...Object.fromEntries(fields.map(key=>[key,form[key]]))}});Object.assign(form,Object.fromEntries(['enabled','environment','producer_source',...fields].map(key=>[key,state.value.settings[key]])));notice.value=form.enabled?'Preparación de pruebas activada para las nuevas facturas emitidas.':'Configuración guardada.';}catch(cause){error.value=verifactuError(cause);}finally{busy.value=false;}}
async function send(row){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const result=await api('/verifactu/records/'+row.id+'/send',{method:'POST',timeoutMs:60000,body:{confirm_test:true}});await load();notice.value='Respuesta del entorno de pruebas: '+fiscalStatus[result.status]+'.';}catch(cause){error.value=verifactuError(cause);}finally{busy.value=false;}}
async function download(path,filename){if(busy.value)return;busy.value=true;error.value='';try{await downloadFile(path,filename);}catch(cause){error.value=verifactuError(cause);}finally{busy.value=false;}}
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{await load();}catch(cause){error.value=verifactuError(cause);}finally{busy.value=false;}}
onMounted(refresh);
</script>
<template>
 <div class="page-heading"><div><h1>VERI*FACTU <span class="badge">Pruebas</span></h1><p class="muted">Configuración y registros de {{ company.name }} para el portal de pruebas de la AEAT.</p></div><button class="button" :disabled="busy" @click="refresh">Actualizar</button></div>
 <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="success-note" role="status">{{ notice }}</p>
 <p class="notice vf-test-note">Preparación en pruebas. Los envíos de esta pantalla van al portal de pruebas externas de la AEAT. La emisión fiscal en producción requiere completar la integración, validar sus casos y disponer de la declaración responsable.</p>
 <template v-if="state">
  <div class="vf-summary"><section class="panel"><span>Preparación</span><strong>{{ state.settings.enabled?'Activada en pruebas':'Pendiente de activar' }}</strong></section><section class="panel"><span>Certificado de la empresa</span><strong>{{ state.certificate.configured?'Instalado en el servidor':state.certificate.error?'Revisar certificado':'Pendiente de instalar' }}</strong></section><section class="panel"><span>Registros / pendientes</span><strong>{{ state.counts.total }} / {{ state.counts.pending }}</strong></section><section class="panel"><span>Aceptados / para revisar</span><strong>{{ state.counts.accepted }} / {{ state.counts.review }}</strong></section></div>
  <section class="panel vf-settings"><h2>Configuración por empresa</h2><p class="muted">Emisor: {{ state.company.name }} · {{ state.company.tax_id||'NIF pendiente' }}. <RouterLink to="/empresas">Editar datos de la empresa</RouterLink></p>
   <ul v-if="state.missing.length" class="vf-missing"><li v-for="item in state.missing" :key="item">{{ item }}</li></ul>
   <p class="muted">Para el programa propio puedes utilizar el nombre fiscal y el NIF de esta empresa como productor. Se rellenan desde su ficha en Empresas. La empresa que desarrolla su programa para uso propio también emite su declaración responsable. <a href="https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu/preguntas-frecuentes/certificacion-sistemas-informaticos-declaracion-responsable.html" target="_blank" rel="noopener noreferrer">Criterio de la AEAT para programas propios</a></p>
   <form @submit.prevent="save"><fieldset :disabled="busy||!can('accounting_write')"><label>Productor del programa<select v-model="form.producer_source" name="vf_producer_source" :disabled="state.counts.total>0" @change="producerChanged"><option value="company">Datos de esta empresa · programa propio</option><option value="custom">Otro productor</option></select></label><p v-if="form.producer_source==='company'" class="muted">El nombre fiscal y el NIF se toman de la empresa seleccionada. <RouterLink to="/empresas">Completar o corregir su ficha</RouterLink></p><div class="form-grid"><label>Nombre fiscal del productor del programa<input v-model="form.producer_name" name="vf_producer_name" maxlength="120" :readonly="state.counts.total>0||form.producer_source==='company'" autocomplete="organization"></label><label>NIF del productor<input v-model="form.producer_nif" name="vf_producer_nif" maxlength="9" :readonly="state.counts.total>0||form.producer_source==='company'" placeholder="Completa el NIF en Empresas" autocapitalize="characters"></label></div>
    <details class="vf-software"><summary>Identificación del programa y de esta instalación</summary><div class="form-grid"><label>Nombre del programa<input v-model="form.software_name" name="vf_software_name" maxlength="30" :readonly="state.counts.total>0" required></label><label>Identificador del programa<input v-model="form.software_id" name="vf_software_id" maxlength="2" :readonly="state.counts.total>0" required></label><label>Versión<input v-model="form.version" name="vf_version" maxlength="50" :readonly="state.counts.total>0" required></label><label>Instalación<input :value="form.installation_id" readonly placeholder="Se asigna al guardar"></label></div></details>
    <label class="vf-enable"><input v-model="form.enabled" name="vf_enabled" type="checkbox" :disabled="state.counts.total>0&&state.settings.enabled">Preparar las nuevas facturas emitidas en el entorno de pruebas.</label>
    <p class="muted">Se generan registros F1 de operaciones nacionales con IVA del 4 %, 10 % o 21 %, con huella encadenada, XML y QR de pruebas. Las facturas contabilizadas desde PDF conservan su condición de documento ya emitido.</p>
    <p v-if="state.counts.total" class="muted">La identificación del programa y los registros se conservan al existir una cadena de facturación.</p>
    <div class="actions"><button class="button primary" :disabled="busy">{{ busy?'Guardando…':'Guardar configuración' }}</button></div></fieldset></form>
   <p class="muted vf-certificate-help">Para probar el envío, instala el certificado .pfx de esta empresa en el servidor. Su contraseña se configura fuera del navegador. Cada empresa utiliza su propio certificado o el de su representante autorizado.</p>
   <p><a href="https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu/informacion-tecnica.html" target="_blank" rel="noopener noreferrer">Documentación técnica de la AEAT</a></p>
  </section>
  <section class="vf-registers"><div class="page-heading"><div><h2>Registros de pruebas</h2><p class="muted">Cadena de la empresa completa, compartida por todos sus ejercicios.</p></div><div class="actions"><button class="button" :disabled="busy||!state.counts.total" @click="download('/verifactu/archive','archivo-verifactu-pruebas-'+company.id+'.json')">Descargar archivo de registros</button></div></div>
   <div class="table-wrap panel"><table><thead><tr><th>Orden / tipo</th><th>Factura</th><th>Generado</th><th>Estado en pruebas</th><th>Huella / CSV</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in records" :key="row.id"><td>{{ row.sequence_no }} · {{ row.kind==='alta'?'Alta':'Anulación' }}</td><td>{{ row.reference }}</td><td>{{ row.generated_at }}</td><td><span class="badge">{{ fiscalStatus[row.status] }}</span><small v-if="row.message" class="vf-record-message">{{ row.error_code }} · {{ row.message }}</small></td><td><details><summary>{{ row.hash.slice(0,12) }}…</summary><code class="vf-hash">{{ row.hash }}</code></details><small v-if="row.csv" class="vf-record-message">CSV: {{ row.csv }}</small></td><td><div class="actions"><button class="button" :disabled="busy" @click="download('/verifactu/records/'+row.id+'/xml','verifactu-pruebas-'+row.id+'.xml')">Descargar XML</button><button v-if="['pending','error'].includes(row.status)" class="button" :disabled="!can('accounting_write')||(busy||!state.can_send)" @click="send(row)">{{ row.status==='error'?'Reintentar en pruebas':'Enviar a AEAT · pruebas' }}</button></div></td></tr><tr v-if="!records.length"><td colspan="6" class="empty-cell">Todavía no hay registros. Al activar la preparación, las nuevas facturas emitidas generan su registro de pruebas.</td></tr></tbody></table></div>
   <p class="muted">Las facturas registradas conservan su trazabilidad. Las anulaciones se usan para facturas emitidas por error; los casos que exigen rectificativa necesitan ese procedimiento específico.</p>
  </section>
 </template><p v-else-if="busy" role="status">Cargando configuración…</p>
</template>